[
    SysEntryPointAttribute(false)
]
public void unblock(AVAUnblockProdTableWorkContract _contract)
{
    List            recIds;
    ListEnumerator  listEnumerator;
    ProdTable       prodTable;

    ttsBegin;

    setPrefix(strFmt('%1 - %2', "@NDX:AVAMaterialRequirements", DateTimeUtil::utcNow()));

    if (_contract.parmInitFromRecord())
    {
        recIds          = _contract.parmRecIdList();
        listEnumerator  = recIds.getEnumerator();

        while (listEnumerator.moveNext())
        {
            prodTable = ProdTable::findRecId(listEnumerator.current(), true);
            this.doUnblock(prodTable);
        }
    }

    ttsCommit;
}

protected void doUnblock(ProdTable _prodTable)
{
    WHSWorkTable    workTable;
    WHSWorkLine     workLine;
    ProdBOM         prodBOM;

    while select workTable
        where workTable.Frozen == NoYes::Yes
           && workTable.WorkStatus != WHSWorkStatus::Cancelled
           && workTable.WorkStatus != WHSWorkStatus::Closed
        exists join RecId from workLine
            where workLine.WorkId == workTable.WorkId
            join RecId from prodBOM
                where prodBOM.InventTransId == workLine.InventTransId
                   && prodBOM.ProdId        == _prodTable.ProdId
    {
        WHSWorkManualUnblock::tryManualUnblockWork(workTable);
    }
}
